{
  "schemaVersion": "0.2",
  "slug": "image",
  "name": "Image",
  "family": "D",
  "status": "experimental",
  "purpose": "Renders an image with loading state, error fallback, and optional caption.",
  "scenarios": [
    "Show a product photo",
    "Display a user avatar with fallback",
    "Present a figure with caption"
  ],
  "props": {
    "src": {
      "type": "string",
      "required": true,
      "description": "Image source URL."
    },
    "alt": {
      "type": "string",
      "required": true,
      "description": "Alternative text; empty string marks decorative images."
    },
    "caption": {
      "type": "string",
      "required": false,
      "description": "Visible caption below the image."
    },
    "errorLabel": {
      "type": "string",
      "required": false,
      "description": "Text shown when the image fails to load."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Image loaded."
    },
    {
      "name": "error",
      "description": "Image failed to load; fallback shown."
    }
  ],
  "composition": {
    "allowedParents": [
      "card",
      "article-card",
      "page",
      "grid"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not omit alt text for informative images.",
    "Do not use an image to present text that could be real text."
  ],
  "a11y": {
    "role": "img",
    "keyboard": [],
    "focus": "Not focusable.",
    "labeling": "alt attribute carries the text alternative; caption uses figcaption.",
    "wcag": [
      "1.1.1"
    ]
  },
  "responsive": {
    "strategy": "Scales to container width while preserving aspect ratio.",
    "breakpoints": {
      "compact": "Full container width.",
      "medium": "Full container width.",
      "large": "Full container width."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "image",
    "states": [
      "default",
      "error"
    ],
    "intents": [
      "signal-meaning"
    ]
  }
}

import { useState } from 'react'
import './styles.css'

export interface ImageProps {
  src: string
  alt: string
  caption?: string
  errorLabel?: string
  className?: string
}

export function Image({ src, alt, caption, errorLabel = 'Image failed to load', className }: ImageProps) {
  const [failed, setFailed] = useState(false)
  const classes = ['cu-image', className].filter(Boolean).join(' ')
  return (
    <figure className={classes} data-ai-role="image" data-ai-intent="signal-meaning" data-ai-state={failed ? 'error' : 'default'}>
      {failed ? (
        <div className="cu-image__fallback" role="img" aria-label={alt}>
          {errorLabel}
        </div>
      ) : (
        <img className="cu-image__img" src={src} alt={alt} loading="lazy" onError={() => setFailed(true)} />
      )}
      {caption ? <figcaption className="cu-image__caption">{caption}</figcaption> : null}
    </figure>
  )
}

{
  "image": {
    "label": "画像",
    "loadError": "画像を読み込めませんでした"
  }
}

.cu-image {
  display: block;
  margin: 0;
  color: var(--cu-color-fg-default);
}

.cu-image__img {
  display: block;
  max-inline-size: 100%;
  block-size: auto;
  border-radius: var(--cu-radius-md);
}

.cu-image__fallback {
  display: flex;
  align-items: center;
  justify-content: center;
  min-block-size: calc(var(--cu-space-3) * 8);
  border: 1px dashed var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  color: color-mix(in srgb, var(--cu-color-fg-default) 72%, transparent);
}

.cu-image__caption {
  margin-block-start: var(--cu-space-1);
  font-size: 0.875em;
  color: color-mix(in srgb, var(--cu-color-fg-default) 72%, transparent);
}
